import json

# Zhang's claim: wearing less in cold (X) causes arthritis (Y).
# An option weakens the claim most if it shows X present, Y absent, in a
# comparable case (same city and habits), without importing an unrelated factor.
# Features are encoded from the text of each option.
options = {
    "A": dict(x_present_y_absent=True,  comparable=False, self_contradictory=True,  supports=False, other_cause_only=False),
    "B": dict(x_present_y_absent=False, comparable=False, self_contradictory=False, supports=True,  other_cause_only=False),
    "C": dict(x_present_y_absent=True,  comparable=True,  self_contradictory=False, supports=False, other_cause_only=False),
    "D": dict(x_present_y_absent=False, comparable=False, self_contradictory=False, supports=False, other_cause_only=True),
}

def weaken_score(f):
    s = 0
    if f["x_present_y_absent"]:
        s += 3
    if f["comparable"]:
        s += 2
    if f["other_cause_only"]:
        s += 1      # shows other causes exist but does not refute X causing Y
    if f["supports"]:
        s -= 3
    if f["self_contradictory"]:
        s -= 2      # A's "because they wear less" is incoherent as a counterexample
    return s

scores = {k: weaken_score(v) for k, v in options.items()}
best = max(scores, key=scores.get)
ties = [k for k, v in scores.items() if v == scores[best]]

if len(ties) != 1:
    print("UNSUPPORTED")
else:
    print(json.dumps({"final_answer": best, "evidence": {"scores": scores}}))
